76	export const memoService = {
77	  async save(
78	    state: EditorState,
79	    options: {
80	      memoName?: string;
81	      parentMemoName?: string;
82	    },
83	  ): Promise<{ memoName: string; hasChanges: boolean }> {
84	    // 1. Upload local files first
85	    const newAttachments = await uploadService.uploadFiles(state.localFiles);
86	    const allAttachments = [...state.metadata.attachments, ...newAttachments];
87	
88	    // 2. Update existing memo
89	    if (options.memoName) {
90	      const prevMemo = await memoServiceClient.getMemo({ name: options.memoName });
91	      const { mask, patch } = buildUpdateMask(prevMemo, state, allAttachments);
92	
93	      if (mask.size === 0) {
94	        return { memoName: prevMemo.name, hasChanges: false };
95	      }
96	
97	      const memo = await memoServiceClient.updateMemo({
98	        memo: create(MemoSchema, patch as Record<string, unknown>),
99	        updateMask: create(FieldMaskSchema, { paths: Array.from(mask) }),
100	      });
101	      return { memoName: memo.name, hasChanges: true };
102	    }
103	
104	    // 3. Create new memo or comment
105	    const memoData = create(MemoSchema, {
106	      content: state.content,
107	      visibility: state.metadata.visibility,
108	      attachments: toAttachmentReferences(allAttachments),
109	      relations: state.metadata.relations,
110	      location: state.metadata.location,
111	      createTime: state.timestamps.createTime ? timestampFromDate(state.timestamps.createTime) : undefined,
112	      updateTime: state.timestamps.updateTime ? timestampFromDate(state.timestamps.updateTime) : undefined,
113	    });
114	
115	    const memo = options.parentMemoName
116	      ? await memoServiceClient.createMemoComment({
117	          name: options.parentMemoName,
118	          comment: memoData,
119	        })
120	      : await memoServiceClient.createMemo({ memo: memoData });
121	
122	    return { memoName: memo.name, hasChanges: true };
123	  },
124	
125	  /**
126	   * Build the INIT_MEMO payload from an already-loaded Memo entity (no network
127	   * request). Returns only the fields the reducer's INIT_MEMO case consumes —
128	   * UI state (mode, loading flags, …) is owned by the reducer, not by memos.
129	   */
130	  fromMemo(memo: Memo): Pick<EditorState, "content" | "metadata" | "timestamps"> {
131	    return {
132	      content: memo.content,
133	      metadata: {
134	        visibility: memo.visibility,
135	        attachments: memo.attachments,
136	        relations: memo.relations,
137	        location: memo.location,
138	      },
139	      timestamps: {
140	        createTime: memo.createTime ? timestampDate(memo.createTime) : undefined,
141	        updateTime: memo.updateTime ? timestampDate(memo.updateTime) : undefined,
142	      },
143	    };
144	  },
145	};
